import { CheckboxState } from "../checkbox/checkboxState";
import { ListAction, SelectDirection } from "./selectList.actionTypes";
import { getFirstActiveIndex, getFirstIndex, getItemIdByIndex, getItemIndexById, getLastIndex, getNextIndex, getPrevIndex, searchItemIndex, updateItemState } from "./selectList.helpers";
const selectItem = (state, itemIndex, multiselect) => {
    const itemId = getItemIdByIndex(state.itemsState, itemIndex);
    if (!itemId) {
        return Object.assign({}, state);
    }
    const [itemsState, isUpdated] = updateItemState(state.itemsState, multiselect, itemId, CheckboxState.On);
    return Object.assign(Object.assign({}, state), { activeIndex: itemIndex, itemsState, isItemsStateChanged: isUpdated, searchStr: "" });
};
const toggleItems = (items, state, activeIndex, direction, multiselect, newState) => {
    if (!multiselect) {
        return Object.assign({}, state);
    }
    let newItemsState = new Map(state.itemsState);
    let isUpdated = false;
    const startIndex = direction === SelectDirection.Up ? 0 : activeIndex;
    const endIndex = direction === SelectDirection.Up ? activeIndex + 1 : items.length;
    const itemsSlice = items.slice(startIndex, endIndex);
    itemsSlice.forEach(item => {
        if (!item.disabled) {
            const itemState = newItemsState.get(item.id);
            const newItemState = newState || (itemState === CheckboxState.On ? CheckboxState.Off : CheckboxState.On); // Toggle state if newState is not defined
            const [updatedState, isItemUpdated] = updateItemState(newItemsState, multiselect, item.id, newItemState);
            newItemsState = updatedState;
            isUpdated = isUpdated || isItemUpdated;
        }
    });
    return Object.assign(Object.assign({}, state), { activeIndex, itemsState: newItemsState, isItemsStateChanged: isUpdated, searchStr: "" });
};
// eslint-disable-next-line complexity
export const selectListReducer = (state, action) => {
    const { type, payload } = action;
    switch (type) {
        case ListAction.ChangeItemState: {
            const [newState, isUpdated] = updateItemState(state.itemsState, payload.multiselect, payload.updatedId, payload.updatedState);
            return Object.assign(Object.assign({}, state), { itemsState: newState, isItemsStateChanged: isUpdated, activeIndex: getItemIndexById(newState, payload.updatedId), searchStr: "" });
        }
        case ListAction.ToggleCurrent: {
            const currentItemId = getItemIdByIndex(state.itemsState, state.activeIndex);
            const currentState = currentItemId && state.itemsState.get(currentItemId) || CheckboxState.Off;
            const [newItemsState, isUpdated] = currentItemId
                ? updateItemState(state.itemsState, payload.multiselect, currentItemId, currentState === CheckboxState.On ? CheckboxState.Off : CheckboxState.On)
                : [state.itemsState, false];
            return Object.assign(Object.assign({}, state), { itemsState: newItemsState, isItemsStateChanged: isUpdated, searchStr: "" });
        }
        case ListAction.FocusFirst: return Object.assign(Object.assign({}, state), { activeIndex: getFirstIndex(payload.items), isItemsStateChanged: false, searchStr: "" });
        case ListAction.FocusLast: return Object.assign(Object.assign({}, state), { activeIndex: getLastIndex(payload.items), isItemsStateChanged: false, searchStr: "" });
        case ListAction.FocusNext: return Object.assign(Object.assign({}, state), { activeIndex: getNextIndex(state.activeIndex, payload.items), isItemsStateChanged: false, searchStr: "" });
        case ListAction.FocusPrev: return Object.assign(Object.assign({}, state), { activeIndex: getPrevIndex(state.activeIndex, payload.items), isItemsStateChanged: false, searchStr: "" });
        case ListAction.SelectFirst: return selectItem(state, getFirstIndex(payload.items), payload.multiselect);
        case ListAction.SelectLast: return selectItem(state, getLastIndex(payload.items), payload.multiselect);
        case ListAction.SelectNext: return selectItem(state, getNextIndex(state.activeIndex, payload.items), payload.multiselect);
        case ListAction.SelectPrev: return selectItem(state, getPrevIndex(state.activeIndex, payload.items), payload.multiselect);
        case ListAction.SelectAllToTheBeginning: return toggleItems(payload.items, state, state.activeIndex, SelectDirection.Up, payload.multiselect, CheckboxState.On);
        case ListAction.SelectAllToTheEnd: return toggleItems(payload.items, state, state.activeIndex, SelectDirection.Down, payload.multiselect, CheckboxState.On);
        case ListAction.ToggleAll: return toggleItems(payload.items, state, 0, SelectDirection.Down, payload.multiselect);
        case ListAction.SearchItem: {
            const isSymbol = payload.key.length === 1;
            const isBackSpace = payload.key === "Backspace";
            let searchStr = state.searchStr;
            if (isSymbol) {
                searchStr += payload.key;
            }
            if (isBackSpace) {
                searchStr = searchStr.slice(0, -1);
            }
            return Object.assign(Object.assign({}, state), { activeIndex: state.searchStr !== searchStr ? searchItemIndex(payload.items, searchStr) : state.activeIndex, isItemsStateChanged: false, searchStr });
        }
        case ListAction.Blur: {
            return Object.assign(Object.assign({}, state), { isItemsStateChanged: false, searchStr: "", activeIndex: -1 });
        }
        case ListAction.Focus: {
            return Object.assign(Object.assign({}, state), { isItemsStateChanged: false, activeIndex: state.activeIndex > -1 ? state.activeIndex : getFirstActiveIndex(state.itemsState, payload.items, payload.multiselect) });
        }
        case ListAction.FocusPrevPage: {
            const prevPage = state.activeIndex - payload.pageSize;
            const prevIndex = prevPage > -1 ? prevPage : 0;
            return Object.assign(Object.assign({}, state), { isItemsStateChanged: false, activeIndex: getPrevIndex(prevIndex + 1, payload.items), searchStr: "" });
        }
        case ListAction.FocusNextPage: {
            const nextPage = state.activeIndex + payload.pageSize;
            const nextIndex = nextPage < payload.items.length ? nextPage : payload.items.length - 1;
            return Object.assign(Object.assign({}, state), { isItemsStateChanged: false, activeIndex: getNextIndex(nextIndex - 1, payload.items), searchStr: "" });
        }
        case ListAction.Reset: {
            const newState = payload.value;
            const filteredMergedState = [...payload.value, ...state.itemsState].filter(([key]) => payload.items.find(item => item.id === key));
            let newItemsState = new Map(filteredMergedState);
            payload.items.forEach(item => {
                const newItemState = newState.get(item.id) || CheckboxState.Off;
                const [updatedState] = updateItemState(newItemsState, payload.multiselect, item.id, newItemState);
                newItemsState = updatedState;
            });
            const prevActiveItemId = getItemIdByIndex(state.itemsState, state.activeIndex);
            const newActiveItemIndex = !!prevActiveItemId && getItemIndexById(newItemsState, prevActiveItemId);
            const activeIndex = newActiveItemIndex ? newActiveItemIndex : -1;
            return Object.assign(Object.assign({}, state), { itemsState: newItemsState, activeIndex, isItemsStateChanged: false });
        }
        case ListAction.SetLevel: {
            const item = payload ? payload.items[state.activeIndex] : undefined;
            const newLevel = item && item.multiLevel ? item.id : "";
            return Object.assign(Object.assign({}, state), { level: newLevel });
        }
        default: throw new Error("Unknown action");
    }
};
